const char* PeerSession::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::PeerSession>(message.name())) {
      case messages::PeerSession::kStart:
            return "Receive remoting::mojom::PeerSession::Start";
      case messages::PeerSession::kStartTransport:
            return "Receive remoting::mojom::PeerSession::StartTransport";
      case messages::PeerSession::kProcessTransportInfo:
            return "Receive remoting::mojom::PeerSession::ProcessTransportInfo";
      case messages::PeerSession::kDisconnectSession:
            return "Receive remoting::mojom::PeerSession::DisconnectSession";
    }
  } else {
    switch (static_cast<messages::PeerSession>(message.name())) {
      case messages::PeerSession::kStart:
            return "Receive reply remoting::mojom::PeerSession::Start";
      case messages::PeerSession::kStartTransport:
            return "Receive reply remoting::mojom::PeerSession::StartTransport";
      case messages::PeerSession::kProcessTransportInfo:
            return "Receive reply remoting::mojom::PeerSession::ProcessTransportInfo";
      case messages::PeerSession::kDisconnectSession:
            return "Receive reply remoting::mojom::PeerSession::DisconnectSession";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

